const readMaintenanceSuppressionWitness = `-- name: ReadMaintenanceSuppressionWitness :one
WITH assignment AS MATERIALIZED (
    SELECT a.service_id, a.effective_at, s.archived_at, (
        SELECT subsequent.effective_at FROM public.almanac_slo_service_assignments subsequent
        WHERE subsequent.slo_id = a.slo_id
          AND (subsequent.effective_at, subsequent.definition_revision) > (a.effective_at, a.definition_revision)
        ORDER BY subsequent.effective_at, subsequent.definition_revision LIMIT 1
    ) AS joined_other_service_at
    FROM public.almanac_slo_service_assignments a
    JOIN public.almanac_services s ON s.id = a.service_id
    WHERE a.slo_id = $2 AND a.effective_at <= $1::timestamptz
    ORDER BY a.effective_at DESC, a.definition_revision DESC LIMIT 1
), candidates AS (
    SELECT r.exclusion_id, r.revision, r.starts_at, r.ends_at, r.recorded_at
    FROM public.almanac_maintenance_exclusion_scopes selected
    JOIN public.almanac_maintenance_exclusion_revisions r
      ON r.exclusion_id = selected.exclusion_id AND r.revision = selected.revision
    WHERE selected.slo_id = $2 AND r.scope_kind = 'slos' AND NOT r.tombstone
      AND tstzrange(r.starts_at, r.ends_at, '[)') @> $1::timestamptz
    UNION ALL
    SELECT r.exclusion_id, r.revision, GREATEST(r.starts_at, a.effective_at), LEAST(r.ends_at, a.archived_at, a.joined_other_service_at), r.recorded_at
    FROM assignment a
    JOIN public.almanac_maintenance_service_selectors selected ON selected.service_id = a.service_id
    JOIN public.almanac_maintenance_exclusion_revisions r
      ON r.exclusion_id = selected.exclusion_id AND r.revision = selected.revision
    WHERE (a.archived_at IS NULL OR a.archived_at > $1::timestamptz)
      AND r.scope_kind = 'services' AND NOT r.tombstone
      AND tstzrange(r.starts_at, r.ends_at, '[)') @> $1::timestamptz
    UNION ALL
    SELECT r.exclusion_id, r.revision, GREATEST(r.starts_at, a.effective_at), LEAST(r.ends_at, a.archived_at, a.joined_other_service_at), r.recorded_at
    FROM assignment a CROSS JOIN public.almanac_maintenance_exclusion_revisions r
    WHERE (a.archived_at IS NULL OR a.archived_at > $1::timestamptz)
      AND r.scope_kind = 'all_services' AND NOT r.tombstone
      AND tstzrange(r.starts_at, r.ends_at, '[)') @> $1::timestamptz
)
SELECT c.exclusion_id, c.revision, c.starts_at, c.ends_at
FROM candidates c
WHERE c.recorded_at <= $1::timestamptz
  AND c.revision = (
      SELECT latest.revision
      FROM public.almanac_maintenance_exclusion_revisions latest
      WHERE latest.exclusion_id = c.exclusion_id AND latest.recorded_at <= $1::timestamptz
      ORDER BY latest.revision DESC LIMIT 1
  )
ORDER BY c.exclusion_id, c.revision
LIMIT 1
`

type ReadMaintenanceSuppressionWitnessParams struct {
	Cutoff pgtype.Timestamptz `json:"cutoff"`
	SloID  pgtype.UUID        `json:"slo_id"`
}

type ReadMaintenanceSuppressionWitnessRow struct {
	ExclusionID pgtype.UUID        `json:"exclusion_id"`
	Revision    int64              `json:"revision"`
	StartsAt    pgtype.Timestamptz `json:"starts_at"`
	EndsAt      pgtype.Timestamptz `json:"ends_at"`
}

// A witness is sufficient to suppress an occurrence. Look up the membership
// and immutable selector revision effective at the evaluation cutoff. Projection
// state cannot participate in this decision. Timestamps establish eligibility
// at the cutoff; the immutable revision sequence establishes precedence.
func (q *Queries) ReadMaintenanceSuppressionWitness(ctx context.Context, arg ReadMaintenanceSuppressionWitnessParams) (ReadMaintenanceSuppressionWitnessRow, error) {
	row := q.db.QueryRow(ctx, readMaintenanceSuppressionWitness, arg.Cutoff, arg.SloID)
	var i ReadMaintenanceSuppressionWitnessRow
	err := row.Scan(
		&i.ExclusionID,
		&i.Revision,
		&i.StartsAt,
		&i.EndsAt,
	)
	return i, err
}

const summarizeScopedSloMaintenanceOverflow = `-- name: SummarizeScopedSloMaintenanceOverflow :one
WITH latest AS MATERIALIZED (
    SELECT DISTINCT ON (c.exclusion_id) c.exclusion_id, c.exclusion_revision, c.included, c.effective_coverage
    FROM public.almanac_slo_exclusion_changes c
    WHERE c.slo_id = $3
    ORDER BY c.exclusion_id, c.revision DESC
)
SELECT count(*) AS window_count,
       min(greatest(lower(segment), $1::timestamptz))::timestamptz AS starts_at,
       max(least(upper(segment), $2::timestamptz))::timestamptz AS ends_at
FROM latest c
CROSS JOIN LATERAL unnest(public.almanac_effective_maintenance_coverage($3, c.exclusion_id, c.exclusion_revision, c.effective_coverage)) segment
WHERE c.included
  AND segment && tstzrange($1::timestamptz, $2::timestamptz, '[)')
  AND (lower(segment), c.exclusion_id) > ($4::timestamptz, $5::uuid)
`

type SummarizeScopedSloMaintenanceOverflowParams struct {
	WindowStart pgtype.Timestamptz `json:"window_start"`
	WindowEnd   pgtype.Timestamptz `json:"window_end"`
	SloID       pgtype.UUID        `json:"slo_id"`
	AfterTime   pgtype.Timestamptz `json:"after_time"`
	AfterID     pgtype.UUID        `json:"after_id"`
}

type SummarizeScopedSloMaintenanceOverflowRow struct {
	WindowCount int64              `json:"window_count"`
	StartsAt    pgtype.Timestamptz `json:"starts_at"`
	EndsAt      pgtype.Timestamptz `json:"ends_at"`
}

func (q *Queries) SummarizeScopedSloMaintenanceOverflow(ctx context.Context, arg SummarizeScopedSloMaintenanceOverflowParams) (SummarizeScopedSloMaintenanceOverflowRow, error) {
	row := q.db.QueryRow(ctx, summarizeScopedSloMaintenanceOverflow,
		arg.WindowStart,
		arg.WindowEnd,
		arg.SloID,
		arg.AfterTime,
		arg.AfterID,
	)
	var i SummarizeScopedSloMaintenanceOverflowRow
	err := row.Scan(&i.WindowCount, &i.StartsAt, &i.EndsAt)
	return i, err
}
